// Tamaño en bytes de un documento BSON, calculado a mano con las reglas del formato.
const enc = new TextEncoder();
const clave = (k) => 1 + enc.encode(k).length + 1;          // byte de tipo + nombre + byte nulo
const texto = (s) => 4 + enc.encode(s).length + 1;           // largo (4) + bytes UTF-8 + nulo
const doc = (campos) => 4 + campos.reduce((a, c) => a + c, 0) + 1;   // largo total (4) + campos + cierre

const evento = doc([
  clave('ts') + 8,                       // fecha: 8 bytes
  clave('tipo') + texto('en_deposito'),
  clave('deposito') + texto('Barracas'),
]);
console.log('un evento mide', evento, 'bytes');

// Un documento con un arreglo de n eventos. Cada elemento lleva por nombre su posición ("0", "1", ...).
const TOPE = 16 * 1024 * 1024;
const fijo = doc([clave('codigo') + texto('GIGA'), clave('eventos') + 4 + 1]);   // todo menos los elementos
let total = fijo, n = 0;
while (total + clave(String(n)) + evento <= TOPE) { total += clave(String(n)) + evento; n += 1; }
console.log('el tope es', TOPE, 'bytes');
console.log('entran', n, 'eventos y el documento mide', total, 'bytes');
console.log('con uno más mediría', total + clave(String(n)) + evento);

