async function mover(n, falla) {
  const s = cli.startSession();
  try {
    await s.withTransaction(async () => {
      await stock.updateOne({ _id: 'Pompeya' }, { $inc: { bultos: -n } }, { session: s });
      if (falla) throw new Error('se cayó el sistema a mitad de camino');
      await stock.updateOne({ _id: 'Barracas' }, { $inc: { bultos: n } }, { session: s });
    });
    console.log('commit ok');
  } catch (e) { console.log('transacción abortada:', e.message); }
  finally { await s.endSession(); }
  console.log(JSON.stringify(await stock.find().sort({ _id: 1 }).toArray()));
}
